#include "protocol.h"
#define HEADER 8u
static uint16_t crc16(const uint8_t *p, size_t n) { uint16_t c=0xffff; for(size_t i=0;i<n;i++){ c^=(uint16_t)p[i]<<8; for(int b=0;b<8;b++) c=(c&0x8000u)?(uint16_t)((c<<1)^0x1021u):(uint16_t)(c<<1); } return c; }
int mm_encode(const mm_message *m,uint8_t*out,size_t cap,size_t*written){ if(!m||!out||!written||m->version!=1||m->length>MM_MAX_PAYLOAD||cap<HEADER+m->length+2u)return -1; out[0]=m->version;out[1]=m->type;out[2]=(uint8_t)(m->length>>8);out[3]=(uint8_t)m->length;out[4]=(uint8_t)(m->sequence>>24);out[5]=(uint8_t)(m->sequence>>16);out[6]=(uint8_t)(m->sequence>>8);out[7]=(uint8_t)m->sequence; for(uint16_t i=0;i<m->length;i++)out[HEADER+i]=m->payload[i];uint16_t c=crc16(out,HEADER+m->length);out[HEADER+m->length]=(uint8_t)(c>>8);out[HEADER+m->length+1]=(uint8_t)c;*written=HEADER+m->length+2u;return 0;}
int mm_decode(const uint8_t*in,size_t len,mm_message*out){ if(!in||!out||len<HEADER+2u)return -1;uint16_t n=(uint16_t)((uint16_t)in[2]<<8|in[3]);if(in[0]!=1||n>MM_MAX_PAYLOAD||len!=HEADER+n+2u)return -2;uint16_t c=crc16(in,HEADER+n);if(c!=(uint16_t)((uint16_t)in[HEADER+n]<<8|in[HEADER+n+1]))return -3;out->version=in[0];out->type=in[1];out->length=n;out->sequence=(uint32_t)in[4]<<24|(uint32_t)in[5]<<16|(uint32_t)in[6]<<8|in[7];for(uint16_t i=0;i<n;i++)out->payload[i]=in[HEADER+i];return 0;}
